mapper.select:
SELECT id, name, subtitle, description, main_img, price, origin_price, tag, sales_text, shop_name, shipping_from, service, type, is_featured, is_carousel, sort_order, created_at, updated_at FROM products
AND type = #{type}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort_order ASC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM products
AND type = #{type}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
